// Avatar — Adw.Avatar
//
// Generated by bin/11-generate-components. The measurements are Adwaita's, read out
// of its stylesheet. The shape is shadcn/ui's, on Base UI.

import * as React from "react"
import { mergeProps } from "@base-ui/react/merge-props"
import { useRender } from "@base-ui/react/use-render"

import { cn } from "@/lib/utils"
import { Icon } from "@/lib/icon"
import { widget } from "@/lib/widget"
import type { WidgetProps } from "@/lib/widget-props"

export interface AvatarProps
  extends Omit<useRender.ComponentProps<"div">, keyof WidgetProps | "customImage" | "iconName" | "showInitials" | "size" | "text">,
    WidgetProps {
  /** Gdk.Paintable, from Adw.Avatar */
  customImage?: unknown

  /** utf8, from Adw.Avatar */
  iconName?: string

  /** gboolean, from Adw.Avatar */
  showInitials?: boolean

  /** gint, from Adw.Avatar */
  size?: number

  /** utf8, from Adw.Avatar */
  text?: string
}

// adw-avatar.c: `(g_str_hash (text) % 14) + 1`, as a class on the gizmo. g_str_hash
// is djb2 over the bytes, so the text is encoded before it is hashed -- a name with
// an accent in it hashed by UTF-16 code unit picked a different colour from the one
// the toolkit picks.
function avatarColor(text: string | undefined) {
  if (!text) return "color1"

  let hash = 5381
  for (const byte of new TextEncoder().encode(text)) hash = (Math.imul(hash, 33) + byte) >>> 0

  return `color${(hash % 14) + 1}`
}

function Avatar({ className, render, iconName, customImage: _customImage, showInitials, size, text, children, ...props }: AvatarProps) {
  const { hidden, className: widgetClassName, style, attributes: widgetAttributes, rest } = widget(props)

  // The label when there are initials to show and the icon when there are not:
  // adw_avatar_set_show_initials toggles exactly one of the two children visible.
  //
  // ONE LETTER PER WORD, which is what adw_avatar_set_text means by initials:
  // `Adwaita::Avatar.new (32, "AL", true)` draws `A`, not `AL`, because "AL" is one
  // word. Shown whole, every avatar in bin/apps/library was a letter wider than the
  // toolkit's and the text was scaled down to fit a circle it should have filled.
  const initials = showInitials && text
    ? text.split(/\s+/).filter(Boolean).map((word) => [...word][0]).join("")
    : null

  const defaultProps = {
    "data-slot": "avatar",
    "data-show-initials": showInitials,
    "data-size": size,
    "data-text": text,
    className: cn("group/avatar", "grid [&>*]:col-start-1 [&>*]:row-start-1", widgetClassName, className),
    style: { ...style, ...(size === undefined ? {} : { minWidth: size }), ...(size === undefined ? {} : { minHeight: size }) } as React.CSSProperties,
    children: (
      <AvatarGizmo className={cn(avatarColor(text), "contrasted", "flex items-center justify-center overflow-hidden")}
        style={{ fontSize: size === undefined ? undefined : `${Math.round(size * 0.4)}px` }}>
        {initials === null ? (
          <AvatarImage name={iconName ?? "avatar-default-symbolic"} style={{ "--adw-icon-size": size === undefined ? undefined : `${Math.round(size * 0.6)}px` } as React.CSSProperties} />
        ) : (
          <AvatarLabel>{initials}</AvatarLabel>
        )}
        {children}
      </AvatarGizmo>
    ),
    ...widgetAttributes,
  }

  return useRender({
    defaultTagName: "div",
    enabled: !hidden,
    render,
    props: mergeProps<"div">(defaultProps, rest),
  })
}

function AvatarSelection({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="avatar-selection"
        data-node="selection"
      className={cn("bg-[color-mix(in_srgb,var(--view-fg-color)_10%,transparent)] text-[transparent]", className)}
      {...props}
    />
  )
}

function AvatarLink({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="avatar-link"
        data-node="link"
      className={cn([
        "text-[var(--accent-color)] [font-weight:inherit] [outline-width:0px] [outline-style:solid] [outline-color:transparent] outline-offset-[4px] transition-[outline-color,outline-width,outline-offset] duration-200 ease-[cubic-bezier(0.25,0.46,0.45,0.94)]",
        "group-hover/avatar:text-[HSL(from_var(--accent-color)_h_calc(s_*_1.1)_calc(l_*_1.1))]",
        "group-active/avatar:text-[var(--accent-color)]",
        "group-disabled/avatar:text-[color-mix(in_srgb,currentColor_var(--disabled-opacity),transparent)]",
      ], className)}
      {...props}
    />
  )
}

function AvatarLabel({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="avatar-label"
        data-node="label"
      className={cn("flex justify-center items-center", [
        "caret-[currentColor]",
        "group-disabled/avatar:[filter:Opacity(var(--disabled-opacity))]",
      ], className)}
      {...props}
    />
  )
}

function AvatarImage({ className, ...props }: React.ComponentProps<typeof Icon>) {
  return (
    <Icon
      data-slot="avatar-image"
        data-node="image"
      className={cn("self-center", className)}
      {...props}
    />
  )
}

function AvatarImage2({ className, ...props }: React.ComponentProps<typeof Icon>) {
  return (
    <Icon
      data-slot="avatar-image2"
        data-node="image"
      className={cn("self-center", className)}
      {...props}
    />
  )
}

function AvatarGizmo({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="avatar-gizmo"
        data-node="avatar"
      className={cn("flex flex-row [&>[data-hexpand]]:grow [&>[data-valign=start]]:self-start [&>[data-valign=center]]:self-center [&>[data-valign=end]]:self-end [&>[data-valign=baseline]]:self-baseline", "rounded-full font-bold", className)}
      {...props}
    />
  )
}

export { Avatar, AvatarSelection, AvatarLink, AvatarLabel, AvatarImage, AvatarImage2, AvatarGizmo }
